import {seed,sum,money,plan,demand,cost,selectedPlan,approve,validateRecord,checkMidday,outcome,clone,unitCost} from './model.js';
const KEY='tantsa-demo-v1';
function hydrate(saved){const base=seed();if(!saved||![1,2].includes(saved.version))return base;const products=(saved.products||base.products).map((p,i)=>({...p,unit:p.unit||base.products[i]?.unit||'unit'}));return {...base,...saved,version:2,business:{...base.business,...(saved.business||{})},products};}
let state;try{state=hydrate(JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('saktoserve-demo-v1')));}catch{state=seed();}
const icons=['◫','＋','▦','✓','◷','▤'];
const pages=[['today','Today'],['record','Quick record'],['plan',"Tomorrow’s plan"],['review','Review & approve'],['midday','Midday check'],['end','Day-end review']];
let settings=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>`&#${c.charCodeAt(0)};`);
const product=(p,i)=>`<div class="product"><span class="product-icon p${i%3}">0${i+1}</span><div><b>${esc(p.name)}</b><small>${money(p.price)} / ${esc(p.unit||'unit')}</small></div></div>`;
const btn=(text,action,kind='')=>`<button class="button ${kind}" data-action="${action}">${text}</button>`;
const heading=(eyebrow,title,sub,action='')=>`<header class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</header>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage is unavailable. Keep this tab open.');}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3200);}
function go(view){state.view=view;save();render();window.scrollTo({top:0,behavior:'instant'});}
function stat(label,value,note,highlight=false,icon='◦'){return `<div class="stat ${highlight?'highlight':''}"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><strong>${value}</strong><small>${note}</small></div>`;}

function workflowStepper(){
  const steps=[
    {id:'record',icon:'🌅',num:1,label:'1. Kahapon',sub:'Record'},
    {id:'plan',icon:'💰',num:2,label:'2. Puhunan',sub:'Budget & Plan'},
    {id:'review',icon:'✍️',num:3,label:'3. Desisyon',sub:'Approve'},
    {id:'midday',icon:'☀️',num:4,label:'4. Tanghali',sub:'12:00 PM Check'},
    {id:'end',icon:'🌙',num:5,label:'5. Ulat ng Araw',sub:'Closing'}
  ];
  return `<nav class="stepper-bar" aria-label="Workflow progress">${steps.map(s=>{
    const isActive=state.view===s.id;
    const isDone=(s.id==='record'&&state.today)||(s.id==='plan'&&state.approval)||(s.id==='review'&&state.approval)||(s.id==='midday'&&state.midday?.decision)||(s.id==='end'&&state.outcome);
    return `<button class="step-item ${isActive?'active':isDone?'done':''}" data-action="nav:${s.id}" ${isActive?'aria-current="step"':''}><span class="step-badge">${isDone&&!isActive?'✓':s.num}</span><div><b>${s.label}</b> <small class="muted">· ${s.sub}</small></div></button>`;
  }).join('')}</nav>`;
}

function scenarioBar(){
  return `<div class="scenario-bar"><span>💡 1-Tap Subukan ang Sitwasyon (Demo):</span><button class="scenario-chip" data-action="scenario:typical">🍞 Tipikal na Araw</button><button class="scenario-chip" data-action="scenario:fast">⚡ Mabilis ang Benta</button><button class="scenario-chip" data-action="scenario:slow">🌧️ Mahina / Maulan</button></div>`;
}

function today(){const t=state.today,p=plan(state),remaining=sum(t.prepared)-sum(t.sold)-sum(t.discarded);return `${scenarioBar()}${heading('Ngayon',`Magandang araw, ${esc(state.business.owner)}.`,'Isang malinaw na simula para bukas.',btn('＋ &nbsp; Quick record (Kahapon)','nav:record','lime big-action-btn'))}<div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Ginawa',sum(t.prepared),`${state.products.length} configured products`,false,'▦')}${stat('Nabenta',sum(t.sold),`${Math.round(sum(t.sold)/sum(t.prepared)*100)}% ng nagawa`,false,'↗')}${stat('Natira',remaining,'pyesa para sa walk-in',true,'◫')}</div><div class="cols"><div class="stack"><section class="card"><div class="card-head"><div><h2>Nasa counter ngayon</h2><p>Today’s production and sales</p></div><span class="pill">${esc(state.business.type)} bukas</span></div><div class="table-wrap"><table><thead><tr><th>Produkto</th><th>Ginawa</th><th>Nabenta</th><th>Natira</th></tr></thead><tbody>${state.products.map((pr,i)=>`<tr><td>${product(pr,i)}</td><td>${t.prepared[i]}</td><td>${t.sold[i]}</td><td><span class="remaining">${t.prepared[i]-t.sold[i]-t.discarded[i]} pyesa</span></td></tr>`).join('')}</tbody></table></div><div class="card-foot"><span>May ${sum(t.preorderSold)} nakuhang preorders</span><button class="link" data-action="nav:record">Baguhin ang bilang ↗</button></div></section><details class="card" style="border:1px solid var(--line);border-radius:13px;box-shadow:var(--shadow);overflow:hidden"><summary style="padding:16px 20px;cursor:pointer;font-weight:600;font-size:14px;color:var(--green);list-style:none">Kasaysayan ng Benta <span style="color:var(--muted);font-weight:400;font-size:12px">· ipakita</span></summary><div class="card-head" style="display:none"><div><h2>Kasaysayan ng Benta</h2><p>Sample Friday walk-in sales · preorders excluded</p></div><span class="tag">${state.history.filter(h=>h.day==='Friday').length} kahalintulad na Biyernes</span></div><div class="chart">${state.history.filter(h=>h.day==='Friday').map(h=>`<div class="chart-row"><span>${h.date}</span><div class="bar-track"><div class="bar" style="width:${sum(h.walkin)/1.2}%"></div></div><b>${sum(h.walkin)}</b></div>`).join('')}<div class="chart-row target"><span>Tantsa</span><div class="bar-track"><div class="bar" style="width:${Math.min(100,sum(p.walkin)/1.2)}%"></div></div><b>${sum(p.walkin)}</b></div><div class="legend"><span><i class="dot"></i>Aktwal na walk-ins</span><span><i class="dot dark"></i>Tantsa para bukas</span></div></div></details></div><div class="stack"><section class="card plan-card"><div class="eyebrow">Para bukas</div><h2>Maghanda nang may plano.</h2><div class="plan-total"><strong class="big">${sum(p.total)}</strong><span>pyesa, pinakamarami</span></div><div class="plan-formula">${sum(p.walkin)} tantyang walk-ins + ${sum(state.orders)} siguradong orders</div><p>Simulan nang mas kaunti sa umaga. Hayaang ang tanghali ang magpasya sa susunod na batch.</p><div class="split"><div><strong>${sum(p.initial)}</strong><small>Unang lutuin (Morning)</small></div><div><strong>${sum(p.conditional)}</strong><small>Kondisyonal sa tanghali</small></div></div>${btn('Plano bukas <span>→</span>','nav:plan','lime big-action-btn')}</section></div>`;}
function initials(name){return String(name||'SS').split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase();}
function render(){document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand" data-action="nav:today" role="button" tabindex="0"><img src="logo.png" alt="TANTSA Logo" class="brand-logo"><div>TANT<span>SA</span></div></div><div class="brand-caption">Guess less. Make right. Earn more.</div><div class="nav-label">ARAW-ARAW NA GABAY</div><nav class="nav" aria-label="Daily workflow">${pages.map(([id,title],i)=>`<button data-action="nav:${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}><span class="nav-icon">${icons[i]}</span>${title}<span class="nav-num">${i+1}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="nav"><button data-action="settings"><span class="nav-icon">⚙</span>Business & products</button><button data-action="reset"><span class="nav-icon">↺</span>Reset demo</button></div><div class="business-id"><div class="avatar">${initials(state.business.name)}</div><div><strong>${esc(state.business.name)}</strong><small>Fictional ${esc(state.business.type.toLowerCase())} · sample data</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">${esc(state.business.name)} &nbsp; / &nbsp; <b>${pages.find(p=>p[0]===state.view)?.[1]||'Today'}</b></div><div class="brand mobile-brand" data-action="nav:today" role="button" tabindex="0"><img src="logo.png" alt="TANTSA Logo" class="brand-logo"><div>TANT<span>SA</span></div></div><div class="top-right"><button class="topbar-action-btn mobile-only-btn" data-action="settings" title="Settings" aria-label="Settings">⚙</button><button class="topbar-action-btn mobile-only-btn" data-action="reset" title="Reset demo" aria-label="Reset demo">↺</button><div class="avatar">${initials(state.business.owner)}</div></div></header><main class="main"><div class="content-enter">${screen()}</div><footer class="footer"><span>Mabilis na tantsa para sa panaderia at food microbusiness.</span><span><button class="link" data-action="settings">Settings</button> · <button class="link" data-action="reset">Reset demo</button></span></footer></main></div></div>${settings?settingsPanel():''}`;}
function screen(){return ({today,record,plan:planning,review,midday,end}[state.view]||today)();}
function planning(){const p=plan(state),shortfall=sum(p.target)-sum(p.total);return `${heading('HAKBANG 2: BIYERNES · TOMORROW','Kasya sa Puhunan.','Magsimula sa kung anong meron ka. Magplano ayon sa kayang dalhin ng pera mo.')}<div class="cols"><div class="stack"><section class="card form-card"><div style="display:flex;justify-content:space-between;align-items:center"><h2>Puhunan sa Sangkap (Purchasing Budget)</h2><span class="pill">Kasya sa Puhunan</span></div><p class="small" style="margin-top:8px">Pera na nakalaan pambili ng dagdag na sangkap bukas. Kasama rin ang natitirang stock sa kusina.</p><label class="budget-value">₱ <input id="budget" aria-label="Purchasing budget in pesos" type="number" min="0" max="10000" step="1" value="${state.budget/100}" data-field="budget"></label><input class="budget-slider" aria-label="Adjust purchasing budget" type="range" min="0" max="2500" step="25" value="${Math.min(2500,state.budget/100)}" data-field="budget"><div class="range-labels"><span>₱0 · gamit ang stock</span><span>₱2,500</span></div><div class="budget-buttons">${[0,150,300,500,1000,1500].map(n=>`<button class="${state.budget===n*100?'active':''}" data-action="budget:${n}">${money(n*100)}</button>`).join('')}</div><div class="notice ${p.errors.length?'error':shortfall?'warn':''}"><strong>${p.errors.length?'May kailangang ayusin sa confirmed orders':shortfall?`${shortfall} walk-in units ang pinigil muna`:'Kasya ang buong plano!'}</strong>${p.errors.length?p.errors.join(' '):shortfall?`Sa puhunang ${money(state.budget)}, kasya ang ${sum(p.total)} sa ${sum(p.target)} target units. Lahat ng ${sum(state.orders)} siguradong order ay protektado.`:`${money(p.cash)} ang kailangan para sa mga bibilhing pakete. ${money(state.budget-p.cash)} ang natira sa iyong puhunan.`}</div><hr class="divider"><h3>Siguradong Preorders (Orders Bukas)</h3><p class="small" style="margin-top:5px">Nakalaan agad sa unang pagluluto. Hiwalay sa inaasahang walk-in.</p><div class="input-grid">${state.products.map((pr,i)=>`<div class="field card" style="padding:14px;border:1px solid var(--line);box-shadow:none"><div style="font-weight:700;font-size:13.5px;color:var(--ink)">${esc(pr.name)}</div><span class="taglish-hint">Siguradong order (pyesa)</span><div class="num-stepper" style="margin-top:10px"><button type="button" class="step-btn" data-action="step-field" data-field="order" data-index="${i}" data-delta="-1">−</button><input type="number" min="0" max="600" step="1" value="${state.orders[i]}" data-field="order" data-index="${i}" aria-label="${pr.name} confirmed preorders"><button type="button" class="step-btn" data-action="step-field" data-field="order" data-index="${i}" data-delta="1">+</button></div></div>`).join('')}</div><p class="small">${sum(state.orders)} pyesang komitido · hindi kailanman binabawasan</p></section><section class="card"><div class="card-head"><div><h2>Bakit ito ang tantsa? (Explainable)</h2><p>${p.source} · batay sa sarili mong benta</p></div><span class="pill sample">Confidence: ${p.limited?'Low · limited baseline':'Moderate · 3 comparable Fridays'}</span></div><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>WALK-INS</th><th>PREORDERS</th><th>TARGET</th></tr></thead><tbody>${state.products.map((pr,i)=>`<tr><td>${product(pr,i)}</td><td>${p.walkin[i]}</td><td>+ ${state.orders[i]}</td><td><b>${p.target[i]}</b></td></tr>`).join('')}</tbody></table></div><div style="padding:14px 24px;background:#f9faf6;border-top:1px solid var(--line);font-size:13px;line-height:1.6"><strong>Paliwanag sa tantsa:</strong><p style="margin-top:4px;color:var(--ink)">Ang mga nakaraang Biyernes ay may average na <b>${sum(p.walkin)} walk-in units</b> (72 pyesa kabuuan). Lahat ng <b>${sum(state.orders)} siguradong preorders</b> ay nakalaan na agad. Binuo ang bilang sa tamang oven batch ng ${state.products.map(pr=>pr.batch).join(', ')}.</p></div><div class="accordion"><details><summary>Tingnan ang talaan ng nakaraang mga Biyernes</summary><p>Average ng mga maihahambing na Biyernes, idinagdag ang siguradong preorders nang isang beses, at binuo sa buong batch.</p><table><thead><tr><th>Petsa</th>${state.products.map(pr=>`<th>${pr.name}</th>`).join('')}<th>Preorders</th></tr></thead><tbody>${state.history.filter(h=>h.day==='Friday').map(h=>`<tr><td>${h.date}</td>${h.walkin.map(n=>`<td>${n}</td>`).join('')}<td>${sum(h.preorders)}</td></tr>`).join('')}</tbody></table></details></div></section></div><div class="stack"><section class="card plan-card"><div class="eyebrow">${p.errors.length?'KULANG ANG PUHUNAN':'KASYANG PLANO SA PUHUNAN'}</div><h2>${p.errors.length?'Ayusin bago magluto.':'Magsimula sa ligtas na bilang.'}</h2><div class="plan-total"><strong class="big">${sum(p.total)}</strong><span>pyesa, maximum</span></div><div class="split"><div><strong>${sum(p.initial)}</strong><small>Unang iluluto · ${sum(state.orders)} reserved</small></div><div><strong>${sum(p.conditional)}</strong><small>Kondisyonal sa tanghali</small></div></div><div style="background:#ffffff15;border-radius:8px;padding:10px 14px;margin:12px 0;font-size:12px;line-height:1.5;color:#e8f4e5">⏱ <b>Staged batch rule:</b> Magluto muna ng ${sum(p.initial)} sa umaga. Itabi ang natitirang ${sum(p.conditional)} para sa 12:00 PM check.</div><p>${p.errors.length?'Hindi pa kasya ang mga siguradong order sa puhunan.':'Buong batches. Siguradong orders muna. Ikaw ang mag-aapruba.'}</p>${btn('Suriin at Aprubahan ang Plano →','nav:review','lime big-action-btn')}</section>${costCard(p)}<div class="card form-card"><h3>Kapasidad ng Kusina</h3><div class="math"><span>Oras ng pagluluto</span><b>${p.minutes} / ${state.capacity} min</b><span>Bilang ng batches</span><b>${sum(p.total.map((n,i)=>n/state.products[i].batch))}</b></div><p class="small">Isang sequential preparation station. Kasama ang sangkap ng kondisyonal na batch sa bibilhin.</p></div></div></div>`;}
function costCard(p){const totalContrib=sum((p.perProduct||[]).map(pp=>pp.contribution));return `<section class="card"><div class="card-head"><div><h2>Kasya sa Puhunan</h2><p>Feasible production & expected contribution</p></div><span class="pill">₱${Math.round(p.cash/100)} / ₱${Math.round(state.budget/100)} nagamit</span></div><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>PLANO</th><th>PUHUNAN/PC</th><th>GASTOS SA SANGKAP</th><th>TULONG SA KITA (CONTRIBUTION)</th></tr></thead><tbody>${(p.perProduct||[]).map(pp=>`<tr><td><b>${esc(pp.name)}</b></td><td>${pp.qty} pcs</td><td>${money(pp.unitCost)}</td><td>${money(pp.consumed)}</td><td><b style="color:var(--green)">+${money(pp.contribution)}</b></td></tr>`).join('')}</tbody></table></div><div style="padding:15px 24px;border-top:1px solid var(--line);background:#fafbf7"><div class="math" style="margin:4px 0"><span>Pera para sa bagong bibilhin</span><b>${money(p.cash)}</b><span>Halaga ng magagamit na sangkap</span><b>${money(p.consumed)}</b><span>Inaasahang tubò (gross contribution)</span><b style="color:var(--green);font-size:15px">+${money(totalContrib)}</b></div><p class="small" style="margin-top:8px">Buong pakete ang bibilhin. Nababawasan ang kailangang cash dahil may stock ka pa sa kusina.</p></div><div class="accordion"><details><summary>Listahan ng bibilhing pakete (${p.lines.filter(l=>l.packs>0).length} bibilhin)</summary><div class="table-wrap"><table><thead><tr><th>Sangkap</th><th>Meron</th><th>Kailangan</th><th>Bibilhin</th><th>Pera</th></tr></thead><tbody>${p.lines.map(g=>`<tr><td>${esc(g.name)} (${esc(g.unit)})</td><td>${g.stock}</td><td>${g.used}</td><td>${g.packs} × ${g.pack}</td><td>${money(g.cash)}</td></tr>`).join('')}</tbody></table></div></details></div></section>`;}
function review(){const p=selectedPlan(state);return `${heading('HAKBANG 3: DESISYON NG MAY-ARI','Aprubahan ang Plano Para Bukas.','Baguhin ang bilang gamit ang + o − sa buong batch. May-ari ang may huling pasya.',btn('← Bumalik sa Puhunan','nav:plan','light'))}${state.approval?`<div class="notice"><strong>Na-aprubahan na ang plano at naka-save sa device.</strong>${sum(state.approval.initial)} pyesa sa umaga. ${sum(state.approval.orders)} nakalaan para sa preorders. ${sum(state.approval.conditional)} pyesa sa tanghali. Status: ${state.approval.override==='adjusted'?'Binago ng may-ari':'Tinanggap ang tantsa ni Tantsa'}.</div>`:''}<div class="cols"><div class="stack"><section class="card"><div class="card-head"><div><h2>Production Sheet Para Bukas</h2><p>Pindutin ang + o − para magdagdag o magbawas ng batch nang walang typo.</p></div><button class="link" data-action="restore-plan">Ibalik sa tantsa</button></div><div class="table-wrap"><table class="record-table"><thead><tr><th>PRODUCT</th><th>SIGURADO<br><small class="muted">Preorders</small></th><th>UNANG LUTUIN<br><small class="muted">Initial (Morning)</small></th><th>MAX TOTAL<br><small class="muted">Kabuuan</small></th><th>KONDISYONAL<br><small class="muted">Wait Midday</small></th></tr></thead><tbody>${state.products.map((pr,i)=>`<tr><td>${product(pr,i)}<small class="muted">${pr.batch} / batch</small></td><td><b>${state.orders[i]} pcs</b></td><td><div class="num-stepper"><button type="button" class="step-btn" data-action="step-field" data-field="initial" data-index="${i}" data-delta="-${pr.batch}">−</button><input aria-label="${pr.name} initial quantity" type="number" min="0" max="1200" step="${pr.batch}" value="${p.initial[i]}" data-field="initial" data-index="${i}"><button type="button" class="step-btn" data-action="step-field" data-field="initial" data-index="${i}" data-delta="${pr.batch}">+</button></div></td><td><div class="num-stepper"><button type="button" class="step-btn" data-action="step-field" data-field="total" data-index="${i}" data-delta="-${pr.batch}">−</button><input aria-label="${pr.name} maximum total" type="number" min="0" max="1200" step="${pr.batch}" value="${p.total[i]}" data-field="total" data-index="${i}"><button type="button" class="step-btn" data-action="step-field" data-field="total" data-index="${i}" data-delta="${pr.batch}">+</button></div></td><td><b>${p.conditional[i]} pcs</b></td></tr>`).join('')}</tbody></table></div><div class="summary-strip"><p>UNANG ILULUTO (UMAGA)<strong>${sum(p.initial)} pyesa</strong></p><p>SIGURADONG ORDER<strong>${sum(state.orders)} pyesa</strong></p><p>KONDISYONAL SA TANGHALI<strong>${sum(p.conditional)} pyesa</strong></p></div><div style="padding:14px 24px;background:#edf3e6;color:#33562e;border-top:1px solid var(--line);font-size:12.5px;line-height:1.5">⏱ <b>Staged batch rule:</b> Magluto muna ng <b>${sum(p.initial)} pyesa</b> sa umaga. Hintayin ang 12:00 PM bago simulan ang <b>${sum(p.conditional)} pyesa</b> upang protektahan ang puhunan.</div></section>${p.errors.length?`<div class="notice error"><strong>Hindi pa puwedeng ma-aprubahan ang plano:</strong>${p.errors.map(e=>`<div>${e}</div>`).join('')}</div>`:`<div class="notice"><strong>Handa na para sa desisyon mo.</strong>Lahat ng ${sum(state.orders)} preorders ay protektado, kasya sa puhunang ${money(state.budget)}, at ${p.minutes} minuto ay pasok sa oras ng kusina.</div>`}<div class="card form-card"><h3>Paliwanag para sa may-ari</h3><p class="small" style="margin-top:12px">${sum(p.walkin)} inaasahang walk-ins + ${sum(state.orders)} preorder units = ${sum(p.target)} target units matapos buuin sa batch. ${state.draft?'May ginawa kang sariling adjustment sa bilang.':'Ang tantsa ay nagsisimula sa kalahati ng walk-in demand plus lahat ng siguradong order.'} Nakalaan ang pambiling sangkap para sa buong approved batch, ngunit ang paggawa ng pangalawang batch ay maghihintay sa benta sa tanghali.</p></div></div><div class="stack">${costCard(p)}<section class="card form-card"><h3>Desisyon ng May-ari</h3><div class="math"><span>Kabuuang oras</span><b>${p.minutes} / ${state.capacity} min</b><span>Puhunan</span><b>${money(state.budget)}</b><span>Status</span><b>${state.draft?'Adjusted ng may-ari':'Mungkahi ni Tantsa'}</b></div><div style="display:flex;flex-direction:column;gap:10px;margin-top:16px"><button class="button big-action-btn" style="width:100%" data-action="approve-accept" ${p.errors.length?'disabled':''}>✓ Tanggapin ang plano ni Tantsa (${sum(p.total)} pyesa) →</button>${state.draft?`<button class="button lime big-action-btn" style="width:100%" data-action="approve-adjust" ${p.errors.length?'disabled':''}>✎ I-save ang sarili mong bilang →</button>`:''}<button class="button light" style="width:100%" data-action="reject-plan">✕ I-reset sa orihinal na tantsa</button></div><p class="small" style="margin-top:13px">Naka-save sa device na ito. Ang pag-apruba ay simula ng pagluluto bukas ng umaga.</p></section></div></div>`;}
function record(){const r=state.today;return `${heading('HAKBANG 1: KAHAPON','Kumusta ang benta kahapon?','Ipasok ang ginawa at nabenta gamit ang + o −. Awtomatikong bibilangin ang tira.')}<form id="record-form"><section class="card"><div class="card-head"><div><h2>Talaan ng Benta Kahapon</h2><p>Mabilis na pagpasok ng bilang · ${r.date}</p></div><span class="pill">Buong pyesa</span></div>${recordTable(r,false)}<div style="padding:20px 24px"><label class="checkbox" style="font-weight:600"><input type="checkbox" name="comparable" ${r.comparable?'checked':''}>Gamitin ang araw na ito bilang basehan ng Biyernes</label><p class="small" style="margin-top:8px">Piliin lamang kung inaasahan mong magiging katulad ng mga Biyernes ang dami ng tao bukas.</p></div></section><div id="form-errors" role="alert"></div><div class="action-row"><p>Walk-in history = kabuuang nabenta − preorders. Ang maagang pagkaubos ay palatandaan ng mataas na demand.</p><button class="button lime big-action-btn" type="submit">I-save ang Record at Magplano ng Bukas →</button></div></form>`;}
function recordTable(r,end){const products=end&&state.approval?state.approval.products:state.products;return `<div class="table-wrap"><table class="record-table"><thead><tr><th>PRODUCT</th><th>GINAWA<br><small class="muted">Prepared</small></th><th>LAHAT NG NABENTA<br><small class="muted">Total Sold</small></th><th>SIGURADONG ORDER<br><small class="muted">Preorders</small></th><th>TAPON / SAYANG<br><small class="muted">Discarded</small></th><th>NAUBUSAN AGAD?<br><small class="muted">Early Sellout</small></th></tr></thead><tbody>${products.map((pr,i)=>`<tr><td>${product(pr,i)}<span class="taglish-hint">${pr.batch} bawat batch</span></td>${['prepared','sold','preorderSold','discarded'].map(f=>`<td><div class="num-stepper"><button type="button" class="step-btn" data-action="step-input" data-target="${f}-${i}" data-delta="-${f==='prepared'?pr.batch:1}">−</button><input name="${f}-${i}" aria-label="${pr.name} ${f}" type="number" min="0" max="1200" step="${f==='prepared'?pr.batch:1}" value="${r[f][i]}" required><button type="button" class="step-btn" data-action="step-input" data-target="${f}-${i}" data-delta="${f==='prepared'?pr.batch:1}">+</button></div></td>`).join('')}<td><label class="checkbox" style="font-weight:600"><input aria-label="${pr.name} early sellout" name="early-${i}" type="checkbox" ${r.early?.[i]?'checked':''}>Oo</label></td></tr>`).join('')}</tbody></table></div>`;}
function midday(){const a=state.approval;if(!a)return gated('Kailangan muna ng na-aprubahang plano.','Aprubahan ang plano para bukas bago simulan ang 12:00 PM midday check.');const m=state.midday||middayDefault(a);const result=checkMidday(a,state.midday);const done=!!state.midday?.decision;return `${heading('HAKBANG 4: TANGHALI (12:00 PM CHECK)','Magluto Pa o Maghintay?','Nasa counter na ang unang batch. Tingnan muna ang natitirang benta bago magsalang uli.')}<div class="stats">${stat('Naluto kaninang umaga',sum(a.initial),'pyesa sa unang prep')}${stat('Siguradong preorders',sum(a.orders),'nakatabi para sa nagpa-reserve',true)}${stat('Tira para sa walk-in',sum(a.initial)-sum(a.orders),'puwedeng mabili ngayon')}${stat('Nakatenggang batch',sum(a.conditional),'pyesang naghihintay ng desisyon')}</div><div class="cols"><div class="stack"><form id="midday-form" class="card"><div class="card-head"><div><h2>Ilan ang natitira sa counter ngayon?</h2><p>Hindi kasama ang nakatabing preorder para sa suki</p></div></div><div class="table-wrap"><table class="record-table"><thead><tr><th>PRODUCT</th><th>NABENTANG WALK-IN<br><small class="muted">Morning Sold</small></th><th>TIRA SA ESTANTE<br><small class="muted">Remaining</small></th></tr></thead><tbody>${a.products.map((pr,i)=>`<tr><td>${product(pr,i)}<small class="muted">${a.initial[i]-a.orders[i]} pyesa kaninang umaga</small></td><td><div class="num-stepper"><button type="button" class="step-btn" data-action="step-input" data-target="sold-${i}" data-delta="-1" ${done?'disabled':''}>−</button><input type="number" name="sold-${i}" min="0" max="1200" step="1" required value="${m.sold[i]}" aria-label="${pr.name} midday walk-in sold" ${done?'disabled':''}><button type="button" class="step-btn" data-action="step-input" data-target="sold-${i}" data-delta="1" ${done?'disabled':''}>+</button></div></td><td><div class="num-stepper"><button type="button" class="step-btn" data-action="step-input" data-target="remaining-${i}" data-delta="-1" ${done?'disabled':''}>−</button><input type="number" name="remaining-${i}" min="0" max="1200" step="1" required value="${m.remaining[i]}" aria-label="${pr.name} midday remaining" ${done?'disabled':''}><button type="button" class="step-btn" data-action="step-input" data-target="remaining-${i}" data-delta="1" ${done?'disabled':''}>+</button></div></td></tr>`).join('')}</tbody></table></div><div style="padding:20px 24px"><div id="form-errors" role="alert"></div>${done?'<div class="notice">Naitala na ang desisyon sa tanghali. Tumuloy sa pagsasara ng araw para sa ulat.</div>':`<button class="button lime big-action-btn" type="submit">I-update ang Bilang at Suriin ang Batch →</button><button class="link" type="button" data-action="slow" style="margin-left:14px">Subukan ang mahinang benta</button>`}</div></form><section class="card form-card"><h3>Paano nagpapasya si Tantsa sa tanghali?</h3><p class="small" style="margin-top:10px">Tinitingnan kung mas mabilis ang benta sa umaga kaysa sa natitirang stock. Kung mabilis, magmumungkahi ng panibagong batch. Kung mabagal, ipapayo na i-hold ang pagluluto upang maiwasan ang panis o tapon.</p></section></div><div class="stack"><section class="card form-card"><div class="eyebrow">DESISYON SA SUSUNOD NA BATCH</div><div class="status-title">${done?(m.decision==='delay'?'Na-hold ang dagdag na pagluluto.':'Nailuto ang dagdag na batch.'):result.status==='stale'?'Mag-update muna ng bilang.':result.status==='prepare'?'Mabilis ang benta! Magluto pa.':result.status==='blocked'?'Pakitingnan ang bilang.':'Mabagal ang benta. I-delay muna.'}</div><div class="notice ${['stale','blocked'].includes(result.status)?'warn':''}">${done?'Naka-save na ang iyong desisyon. Ang ulat sa hapon ay ibabatay sa aktwal na naluto.':result.status==='prepare'?`Mabilis ang benta. Maghanda pa ng isa pang batch (${sum(result.batches)} pyesa).`:result.status==='delay'?'Mabagal ang benta. Sapat ang natitira para sa hapon. I-hold muna ang susunod na batch.':result.message}</div>${state.midday&&!done&&['prepare','delay'].includes(result.status)?`<div class="next-batch"><strong>${sum(result.batches)}</strong><span>pyesang mungkahi ngayon<br>sa ${sum(a.conditional)} pyesang nakatengga</span></div>${result.batches.map((n,i)=>n?`<p class="small">${a.products[i].name}: ${n} pyesa</p>`:'').join('')}<button class="button big-action-btn" style="width:100%;margin-top:20px" data-action="midday-decision:${result.status}">${result.status==='prepare'?'I-record: Niluto ang dagdag na batch':'I-record: I-hold muna ang pagluluto'}</button>`:''}${result.status==='delay'?`<div class="notice" style="background:#fef9ee;border:1px solid #fae6be;color:#855c1b;margin-top:14px"><strong>Gawin kung mabagal ang benta bago magsara:</strong><ul style="margin:6px 0 0 16px;padding:0;font-size:12px;line-height:1.6"><li><b>I-hold ang batch:</b> Hindi nagalaw ang sangkap, ligtas ang puhunan.</li><li><b>Mag-markdown:</b> Magbigay ng 20–30% discount bandang alas-kuwatro ng hapon.</li><li><b>I-bundle:</b> Isabay ang natitirang tinapay sa kape o inumin.</li></ul></div>`:''}${done?btn('Pumunta sa Ulat ng Araw (Closing) →','nav:end','big-action-btn'):''}<p class="small" style="margin-top:16px">${state.midday?`Huling update: ${new Date(state.midday.at).toLocaleTimeString('en-PH',{hour:'2-digit',minute:'2-digit'})}`:'Wala pang update sa tanghali.'}</p></section></div></div>`;}
function middayDefault(a){const sold=a.initial.map((n,i)=>Math.floor((n-a.orders[i])*(i===2?1/3:1/2)));return {sold,remaining:sold.map((n,i)=>a.initial[i]-a.orders[i]-n),at:Date.now()};}
function gated(title,text){return `${heading('SUNOD-SUNOD NA ARAWANG GABAY',title,text)}<section class="card empty"><h2>Simulan muna sa plano para bukas.</h2><p>Aprubahan ang dami ng iluluto at bibilhing sangkap bago magsimula ang araw.</p>${btn('Tingnan ang Plano →','nav:review','lime big-action-btn')}</section>`;}
function end(){if(!state.approval)return gated('Ulat ng araw.','Aprubahan ang plano bago i-record ang aktwal na nangyari.');const a=state.approval;const prepared=a.initial.map((n,i)=>n+(state.midday?.prepared?.[i]||0));const r=state.outcome||{prepared,sold:prepared.map((n,i)=>Math.min(n,(state.midday?.sold[i]||0)+a.orders[i])),preorderSold:[...a.orders],discarded:a.products.map(()=>0),early:a.products.map(()=>false)};const o=outcome(state,r);return `${heading('HAKBANG 5: PAGSASARA NG ARAW','Ano ang totoong nangyari?','I-record ang totoong benta at natira upang matuto ang tantsa para bukas.')}<div class="notice ${state.outcome?'':'warn'}"><strong>${state.outcome?'Aktwal na ulat · naka-save sa device':'Draft sa pagsasara'}</strong>${state.outcome?'Ito ang opisyal na resulta ng araw. Gagamitin ito sa tantsa bukas.':'Ang naluto ay batay sa desisyon mo kaninang tanghali. Kumpirmahin ang aktwal na nabenta bago i-save.'}</div><form id="end-form"><section class="card"><div class="card-head"><h2>Huling Bilang sa Counter</h2><span class="tag">Presyo sa tindahan</span></div>${recordTable(r,true)}</section><div id="form-errors" role="alert"></div><div class="action-row"><p>Tira = ginawa − nabenta − tapon. Ang tubò ay kita bawas ang nagamit na sangkap.</p><button class="button lime big-action-btn" type="submit">I-save ang Ulat ng Araw ✓</button></div></form>${state.outcome?`<div class="stats" style="margin-top:26px">${stat('Kabuuang benta (Revenue)',money(o.revenue),`${sum(r.sold)} pyesang nabenta`)}${stat('Natira sa estante (Tira)',o.unsold,'pyesang hindi nabenta')}${stat('Naitapon (Tapon)',o.discarded,'pyesang nasayang')}${stat('Tulong sa Kita (Gross Profit)',money(o.contribution),'benta bawas ang sangkap',true)}</div><section class="card form-card"><h3>Buod ng mga numero ngayong araw</h3><div class="math"><span>Plano sa simula</span><b>${sum(a.total)} pyesa</b><span>Aktwal na naluto</span><b>${sum(prepared)} pyesa</b><span>Aktwal na nabenta</span><b>${sum(r.sold)} pyesa</b><span>Tira sa counter</span><b>${o.unsold} pyesa</b><span>Naitapon / nasayang</span><b>${o.discarded} pyesa</b><span>Naubusan ba nang maaga?</span><b>${r.early?.some(Boolean)?'Oo (Maagang naubusan)':'Hindi (Sapat ang supply)'}</b><span>Desisyon ng may-ari</span><b>${a.override==='adjusted'?'Binago ng may-ari':'Sinunod ang tantsa ni Tantsa'}</b><span>Halaga ng nagamit na sangkap</span><b>${money(o.consumed)}</b><span>Aprubadong badyet</span><b>${money(a.cost.cash)}</b><span>Preorder na nakuha ng suki</span><b>${sum(r.preorderSold)} / ${sum(a.orders)}</b></div><p class="small">Ang hindi nagamit na sangkap ay nananatiling stock sa kusina. Hindi ito itinuturing na tapon.</p></section><section class="card" style="background:var(--deep);color:#e8f0e8;padding:26px 28px;margin-top:24px;border:0;border-radius:12px"><div class="eyebrow" style="color:var(--lime);font-size:11px;letter-spacing:1.8px">ANG ARAW-ARAW NA PAGKATUTO (THE CONTINUOUS LEARNING LOOP)</div><h2 style="color:#fff;font-size:24px;letter-spacing:-0.5px;margin:8px 0 10px">Ang rekomendasyon bukas ay gagamit ng resulta ngayon.</h2><p style="color:#c5d8c7;font-size:13.5px;line-height:1.6;margin:0">Awtomatikong inilagay ni Tantsa ang naging benta ngayong araw sa iyong operating history (kung saan ang preorders ay hiwalay sa walk-in). Sa pagpaplano bukas, mas matalino at mas eksakto na ang tantsa.</p></section>`:''}`;}
function settingsPanel(){return `<div class="settings-overlay"><section class="settings" role="dialog" aria-modal="true" aria-labelledby="settings-title" tabindex="-1"><button class="close" data-action="close-settings" aria-label="Close settings">×</button><h2 id="settings-title">Business & Product Setup</h2><p class="small">Halimbawa lamang ang panaderia. Baguhin ang mga ito para sa carinderia, stall, o café.</p><form id="settings-form"><div class="card form-card"><h3>Impormasyon ng Negosyo</h3><div class="input-grid"><label class="field">Pangalan ng negosyo<input name="business-name" type="text" maxlength="60" required value="${esc(state.business.name)}"></label><label class="field">Uri ng negosyo<input name="business-type" type="text" maxlength="40" required value="${esc(state.business.type)}"></label><label class="field">Pangalan ng may-ari<input name="business-owner" type="text" maxlength="40" required value="${esc(state.business.owner)}"></label></div><p class="small">Halimbawa: Panaderia, Carinderia, Food Stall, Kiosk, Café.</p></div><div class="card"><div class="card-head"><h3>Sangkap at Sukat ng Bibilhin</h3></div><div class="table-wrap"><table><thead><tr><th>SANGKAP</th><th>STOCK SA KUSINA</th><th>SUKAT NG PAKETE</th><th>₱ / PAKETE</th></tr></thead><tbody>${state.ingredients.map((g,i)=>`<tr><td>${esc(g.name)} (${esc(g.unit)})</td><td><input aria-label="${esc(g.name)} stock" name="stock-${i}" type="number" min="0" max="100000" step="1" required value="${g.stock}"></td><td><input aria-label="${esc(g.name)} pack size" name="pack-${i}" type="number" min="1" max="100000" step="1" required value="${g.pack}"></td><td><input aria-label="${esc(g.name)} pack cost in pesos" name="cost-${i}" type="number" min="0.01" max="10000" step="0.01" required value="${g.cost/100}"></td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><div><h3>Mga Produkto at Recipe</h3><p>Awtomatikong kinakalkula ang puhunan bawat pyesa at gross margin.</p></div></div>${state.products.map((p,i)=>`<details><summary><b>${esc(p.name)}</b> <span class="muted">· ${p.batch} pyesa bawat batch · ${money(p.price)}</span></summary><div style="background:#f8faf6;border:1px solid var(--line);border-radius:8px;padding:10px 14px;margin:10px 0;font-size:12.5px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px"><span>Puhunan sa sangkap bawat pyesa: <b>${money(unitCost(state,i))} / ${esc(p.unit||'piece')}</b></span><span>Tubò bawat pyesa: <b style="color:var(--green)">+${money(p.price - unitCost(state,i))}</b> (${Math.round((p.price - unitCost(state,i))/p.price*100)}% margin)</span></div><div class="input-grid"><label class="field">Pangalan ng produkto<input name="name-${i}" type="text" maxlength="40" required value="${esc(p.name)}"></label><label class="field">Tawag sa sukat<input name="unit-${i}" type="text" maxlength="20" required value="${esc(p.unit||'unit')}"></label><label class="field">Presyo ng benta (₱)<input name="price-${i}" type="number" min="0.01" max="10000" step="0.01" required value="${p.price/100}"></label><label class="field">Pyesa bawat lutuan/batch<input name="batch-${i}" type="number" min="1" max="120" step="1" required value="${p.batch}"></label><label class="field">Minuto bawat batch<input name="minutes-${i}" type="number" min="1" max="240" step="1" required value="${p.minutes}"></label></div><p class="small">Kailangang sangkap sa isang buong batch</p>${state.ingredients.map((g,j)=>`<label class="recipe-row">${esc(g.name)} (${esc(g.unit)})<input name="recipe-${i}-${j}" type="number" min="0" max="10000" step="1" required value="${p.recipe[j]}"></label>`).join('')}</details>`).join('')}</div><div class="card form-card"><label class="field">Kapasidad ng kusina bawat araw (minuto)<input name="capacity" type="number" min="0" max="1440" step="1" required value="${state.capacity}"></label><hr class="divider"><label class="checkbox"><input type="checkbox" name="useHistory" ${state.useHistory?'checked':''}>Gamitin ang kasaysayan ng benta</label><p class="small" style="margin-top:10px">Kung walang kasaysayan, gamitin ang baseline na ito:</p><div class="input-grid">${state.products.map((p,i)=>`<label class="field">${esc(p.name)}<input name="fallback-${i}" type="number" min="0" max="600" step="1" required value="${state.fallback[i]||0}"></label>`).join('')}</div></div><div id="settings-errors" role="alert"></div><div class="notice warn">Muling susuriin ang lahat ng plano kapag nagbago ang settings ng negosyo.</div><button type="submit" class="button big-action-btn" style="width:100%">I-save ang Settings</button></form></section></div>`;}
function invalidate(){state.approval=null;state.midday=null;state.outcome=null;}
function setBudget(n){if(!Number.isFinite(n)||n<0||n>10000){toast('Magpasok ng badyet mula ₱0 hanggang ₱10,000.');return;}state.budget=Math.round(n*100);state.draft=null;invalidate();save();render();}
function errors(list,id='form-errors'){document.getElementById(id).innerHTML=list.length?`<div class="notice error">${list.map(t=>`<div>${t}</div>`).join('')}</div>`:'';}
function readRecord(f){const indexes=state.products.map((_,i)=>i);return Object.fromEntries(['prepared','sold','preorderSold','discarded','early'].map(key=>[key,indexes.map(i=>key==='early'?f.has(`${key}-${i}`):Number(f.get(`${key}-${i}`)))]));}

function bindActions(e){
  const el=e.target.closest('[data-action]');
  if(!el)return;
  const action=el.dataset.action;
  if(action.startsWith('nav:'))return go(action.split(':')[1]);
  if(action.startsWith('budget:'))return setBudget(Number(action.split(':')[1]));
  if(action==='settings'){settings=true;render();document.querySelector('.settings').focus();}
  if(action==='close-settings'){settings=false;render();}
  if(action==='reset'){state=seed();settings=false;save();render();window.scrollTo(0,0);toast('Na-reset ang demo para sa 90-second pitch.');}
  if(action==='restore-plan'||action==='reject-plan'){state.draft=null;state.override='none';invalidate();save();render();toast(action==='reject-plan'?'Na-reset ang plano sa mungkahi ni Tantsa.':'Naibalik ang orihinal na bilang.');}
  if(action==='approve'||action==='approve-accept'||action==='approve-adjust'){
    if(action==='approve-accept'){state.draft=null;state.override='none';}
    if(action==='approve-adjust'){state.override='adjusted';}
    if(!state.approval){
      try{
        state.approval=approve(state);
        state.midday=null;
        state.outcome=null;
      }catch(error){
        toast(error.message);
        return;
      }
    }
    go('midday');
    toast(action==='approve-adjust'?'Na-aprubahan ang sarili mong bilang. Handa na ang unang batch.':'Tinanggap ang plano ni Tantsa. Handa na ang unang batch.');
  }
  if(action==='slow'){state.midday=null;render();toast('Mahinang benta: I-save ang bilang para suriin.');}
  if(action.startsWith('midday-decision:')){
    const r=checkMidday(state.approval,state.midday);
    if(!['prepare','delay'].includes(r.status)){toast('I-update muna ang bilang bago magpasya.');render();return;}
    state.midday.decision=r.status;
    state.midday.prepared=r.status==='prepare'?r.batches:state.approval.products.map(()=>0);
    save();
    render();
    toast(r.status==='delay'?'Na-hold ang susunod na batch. Ligtas ang puhunan.':'Naitala ang bagong nilutong batch.');
  }
  if(action==='step-input'){
    const targetName=el.dataset.target;
    const delta=Number(el.dataset.delta||1);
    const input=document.querySelector(`input[name="${targetName}"]`);
    if(input){
      const current=Number(input.value||0);
      const min=Number(input.min||0);
      const max=Number(input.max||1200);
      const next=Math.min(max,Math.max(min,current+delta));
      input.value=next;
      input.dispatchEvent(new Event('input',{bubbles:true}));
      input.dispatchEvent(new Event('change',{bubbles:true}));
    }
    return;
  }
  if(action==='step-field'){
    const f=el.dataset.field;
    const idx=Number(el.dataset.index);
    const delta=Number(el.dataset.delta||1);
    if(f==='order'){
      state.orders[idx]=Math.max(0,(state.orders[idx]||0)+delta);
      state.draft=null;
      invalidate();
      save();
      render();
    }else if(['initial','total'].includes(f)){
      const p=selectedPlan(state);
      state.draft={total:[...p.total],initial:[...p.initial]};
      state.draft[f][idx]=Math.max(0,(state.draft[f][idx]||0)+delta);
      state.override='adjusted';
      invalidate();
      save();
      render();
    }
    return;
  }
  if(action.startsWith('scenario:')){
    const type=action.split(':')[1];
    if(type==='typical'){
      state.today.prepared=[60,36,24];
      state.today.sold=[42,24,15];
      state.today.preorderSold=[12,0,0];
      state.today.discarded=[0,0,0];
      state.today.early=[false,false,false];
      state.orders=[12,0,0];
      state.budget=30000;
      state.draft=null;
      invalidate();
      save();
      render();
      toast('🍞 Tipikal na Araw: Normal sales at 12 preorders.');
    }else if(type==='fast'){
      state.today.prepared=[60,36,24];
      state.today.sold=[60,36,24];
      state.today.preorderSold=[12,0,0];
      state.today.discarded=[0,0,0];
      state.today.early=[true,true,false];
      state.orders=[12,0,0];
      state.budget=60000;
      state.draft=null;
      invalidate();
      save();
      render();
      toast('⚡ Mabilis ang Benta: Naubusan nang maaga, tataas ang mungkahi.');
    }else if(type==='slow'){
      state.today.prepared=[60,36,24];
      state.today.sold=[24,12,6];
      state.today.preorderSold=[12,0,0];
      state.today.discarded=[4,2,1];
      state.today.early=[false,false,false];
      state.orders=[12,0,0];
      state.draft=null;
      invalidate();
      save();
      render();
      toast('🌧️ Mahina / Maulan: May tira sa counter, mag-hold ng batch.');
    }
    return;
  }
}

function bindInputs(e){const el=e.target;const f=el.dataset.field;if(!f)return;const n=Number(el.value),i=Number(el.dataset.index);if(f==='budget')return setBudget(n);if(!Number.isFinite(n)||n<0||n>1200){toast('Magpasok ng bilang mula 0 hanggang 1,200.');return;}if(f==='order'){if(!Number.isSafeInteger(n)){toast('Dapat buong bilang ang preorders.');render();return;}state.orders[i]=n;state.draft=null;}else{const p=selectedPlan(state);state.draft={total:[...p.total],initial:[...p.initial]};state.draft[f][i]=n;state.override='adjusted';}invalidate();save();render();}

function bindForms(e){e.preventDefault();const form=e.target,f=new FormData(form);if(form.id==='record-form'){const r=readRecord(f);const errs=validateRecord(r,state.products,{preorders:true});if(errs.length)return errors(errs);const comparable=f.has('comparable');state.today={...state.today,...r,comparable};state.history=state.history.filter(h=>h.id!=='recorded-today');state.history.push({id:'recorded-today',date:'Sep 24*',day:comparable?'Friday':'Thursday',walkin:r.sold.map((n,i)=>n-r.preorderSold[i]),preorders:r.preorderSold,early:r.early.some(Boolean)});state.draft=null;invalidate();go('plan');toast('Na-save ang record kahapon. Hiwalay ang preorders sa walk-in.');}if(form.id==='midday-form'){const indexes=state.approval.products.map((_,i)=>i);const m={at:Date.now(),sold:indexes.map(i=>Number(f.get(`sold-${i}`))),remaining:indexes.map(i=>Number(f.get(`remaining-${i}`)))};const result=checkMidday(state.approval,m);if(result.status==='blocked')return errors([result.message]);state.midday=m;state.outcome=null;save();render();toast('Sariwang bilang naitala. May rekomendasyon na si Tantsa.');}if(form.id==='end-form'){const r=readRecord(f),o=outcome(state,r);if(o.errors.length)return errors(o.errors);const prepared=state.approval.initial.map((n,i)=>n+(state.midday?.prepared?.[i]||0));if(r.prepared.some((n,i)=>n<prepared[i]))return errors(['Hindi puwedeng mas kaunti ang nagawa kaysa sa nailutong batches.']);if(state.midday&&r.sold.some((n,i)=>n-r.preorderSold[i]<state.midday.sold[i]))return errors(['Hindi puwedeng mas kaunti ang huling benta kaysa sa benta kaninang tanghali.']);state.outcome=r;state.history=state.history.filter(h=>h.id!=='recorded-end');state.history.push({id:'recorded-end',date:'Sep 25*',day:'Friday',walkin:r.sold.map((n,i)=>n-r.preorderSold[i]),preorders:r.preorderSold,early:r.early.some(Boolean)});save();render();toast('Na-save ang aktwal na ulat. Matututo ang plano bukas.');}if(form.id==='settings-form'){const next=clone(state);next.business={name:String(f.get('business-name')||'').trim()||state.business.name,type:String(f.get('business-type')||'').trim()||state.business.type,owner:String(f.get('business-owner')||'').trim()||state.business.owner};next.capacity=Number(f.get('capacity'));next.useHistory=f.has('useHistory');next.fallback=next.products.map((_,i)=>Number(f.get(`fallback-${i}`)));next.ingredients.forEach((g,i)=>{g.stock=Number(f.get(`stock-${i}`));g.pack=Number(f.get(`pack-${i}`));g.cost=Math.round(Number(f.get(`cost-${i}`))*100);});next.products.forEach((p,i)=>{p.name=String(f.get(`name-${i}`)||'').trim()||p.name;p.unit=String(f.get(`unit-${i}`)||'').trim()||'unit';p.price=Math.round(Number(f.get(`price-${i}`))*100);p.batch=Number(f.get(`batch-${i}`));p.minutes=Number(f.get(`minutes-${i}`));p.recipe=next.ingredients.map((_,j)=>Number(f.get(`recipe-${i}-${j}`)));});state=next;state.draft=null;invalidate();settings=false;save();render();toast('Na-save ang settings ng negosyo. Muling kinalkula ang plano.');}}

function trapDialog(e){if(e.key==='Escape'&&settings){settings=false;render();return;}if(e.key!=='Tab'||!settings)return;const els=[...document.querySelector('.settings').querySelectorAll('button,input,summary')].filter(el=>el.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('settings'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}

document.addEventListener('click',bindActions);
document.addEventListener('input',e=>{if(!e.target.dataset.field||e.target.type==='range')return;const id=e.target.id,field=e.target.dataset.field,index=e.target.dataset.index;bindInputs(e);const replacement=id?document.getElementById(id):document.querySelector(`[data-field="${field}"]${index!==undefined?`[data-index="${index}"]`:''}`);replacement?.focus({preventScroll:true});});
document.addEventListener('change',e=>{if(e.target.type==='range')bindInputs(e);});
document.addEventListener('submit',bindForms);
document.addEventListener('keydown',trapDialog);
try{document.modelContext?.registerTool({name:'read_production_plan',title:'Read production plan',description:'Read the current illustrative production plan and constraint warnings without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No arguments expected.');const p=selectedPlan(state);return {total:p.total,initial:p.initial,preorders:state.orders,purchaseCashCentavos:p.cash,consumedCostCentavos:p.consumed,warnings:p.errors};}});}catch{/* Optional browser capability. */}
render();
